// ============================================================
// RIPPING ZACKS — Pikachu Tracker (marketing.html)
// Fully hardcoded — name, card number, target price, and
// ownership status are all maintained directly in this file.
// Update this data only when told to (e.g. "bought the Mario
// Pikachu Promo card" or "set Rayquaza Green to $500").
//
// IMPORTANT: TRACKER_PERMANENT_PHOTOS and its data structure
// must never change — that's where already-uploaded photos live.
// ============================================================

const TRACKER_PERMANENT_PHOTOS = {
  'pretend magikarp pikachu promo': 'data:image/webp;base64,', // 150/XY-P
  'pretend gyarados pikachu promo': 'data:image/webp;base64,', // 151/XY-P
  'poncho-wearing pikachu promo - mega charizard x': 'data:image/webp;base64,', // 207/XY-P
  'poncho-wearing pikachu promo - mega charizard y': 'data:image/webp;base64,', // 208/XY-P
  'poncho-wearing pikachu promo - rayquaza green': 'data:image/webp;base64,', // 230/XY-P
  'poncho-wearing pikachu promo - rayquaza black': 'data:image/webp;base64,', // 231/XY-P
  'mario pikachu promo': 'data:image/webp;base64,', // 293/XY-P
  'mario pikachu promo - full art': 'data:image/webp;base64,', // 294/XY-P
  'luigi pikachu promo': 'data:image/webp;base64,', // 295/XY-P
  'luigi pikachu promo - full art': 'data:image/webp;base64,', // 296/XY-P
  'pretend team skull pikachu promo': 'data:image/webp;base64,', // 013/SM-P
};

// Hardcoded card list — updated by request only.
const TRACKER_ITEMS = [
  { name: 'Pretend Team Skull Pikachu Promo', no: '013/SM-P', price: 0, owned: false },
  { name: 'Pretend Magikarp Pikachu Promo', no: '150/XY-P', price: 0, owned: false },
  { name: 'Pretend Gyarados Pikachu Promo', no: '151/XY-P', price: 0, owned: false },
  { name: 'Poncho-wearing Pikachu Promo - Mega Charizard X', no: '207/XY-P', price: 0, owned: false },
  { name: 'Poncho-wearing Pikachu Promo - Mega Charizard Y', no: '208/XY-P', price: 0, owned: false },
  { name: 'Poncho-wearing Pikachu Promo - Rayquaza Green', no: '230/XY-P', price: 0, owned: false },
  { name: 'Poncho-wearing Pikachu Promo - Rayquaza Black', no: '231/XY-P', price: 0, owned: false },
  { name: 'Mario Pikachu Promo', no: '293/XY-P', price: 0, owned: false },
  { name: 'Mario Pikachu Promo - Full Art', no: '294/XY-P', price: 0, owned: false },
  { name: 'Luigi Pikachu Promo', no: '295/XY-P', price: 0, owned: false },
  { name: 'Luigi Pikachu Promo - Full Art', no: '296/XY-P', price: 0, owned: false },
];

function itemKeyFor(name) {
  return (name || '').trim().toLowerCase();
}

let trackerFilter = 'all';
let trackerSearchTerm = '';

function renderTrackerGrid() {
  const grid = document.getElementById('tracker-grid');
  const count = document.getElementById('tracker-count');
  if (!grid || !count) return;

  const term = trackerSearchTerm.trim().toLowerCase();
  const visible = TRACKER_ITEMS.filter(i => {
    const matchesStatus = trackerFilter === 'all' ||
      (trackerFilter.toLowerCase() === 'own' ? i.owned : !i.owned);
    const matchesSearch = !term || (i.name || '').toLowerCase().includes(term);
    return matchesStatus && matchesSearch;
  });

  count.textContent = visible.length + (visible.length === 1 ? ' card' : ' cards');
  grid.innerHTML = '';

  if (!visible.length) {
    const empty = document.createElement('p');
    empty.style.color = 'var(--ink-faint)';
    empty.textContent = 'No cards match this filter.';
    grid.appendChild(empty);
    return;
  }

  visible.forEach(item => {
    const key = itemKeyFor(item.name);
    const photoSrc = TRACKER_PERMANENT_PHOTOS[key];
    const isOwned = !!item.owned;

    const card = document.createElement('article');
    card.className = 'card-slab';
    if (isOwned) card.classList.add('in-stock');

    // --- label bar: No. on the left, status badge on the right ---
    const label = document.createElement('div');
    label.className = 'card-slab-label';
    label.style.cssText = 'display:flex; justify-content:space-between; align-items:center;';

    const noSpan = document.createElement('span');
    noSpan.textContent = item.no || '';
    noSpan.style.cssText = 'font-family:var(--mono); font-weight:700; font-size:0.85rem; letter-spacing:0.02em; color:var(--ink);';
    label.appendChild(noSpan);

    const statusBadge = document.createElement('span');
    statusBadge.textContent = isOwned ? 'Own' : 'Still looking';
    statusBadge.style.cssText = `font-family:var(--mono); font-weight:700; font-size:0.8rem; text-transform:uppercase; letter-spacing:0.04em; color:${isOwned ? 'var(--mint)' : 'var(--citrus)'};`;
    label.appendChild(statusBadge);

    card.appendChild(label);

    // --- photo ---
    const art = document.createElement('div');
    art.className = 'card-art';
    art.style.position = 'relative';

    if (photoSrc) {
      const img = document.createElement('img');
      img.src = photoSrc;
      img.alt = item.name || '';
      img.style.cssText = 'width:100%;height:100%;object-fit:cover;';
      art.appendChild(img);
    } else {
      art.innerHTML = '<span class="card-glyph">?</span>';
    }
    card.appendChild(art);

    // --- body ---
    const body = document.createElement('div');
    body.className = 'card-body';
    const h3 = document.createElement('h3');
    h3.textContent = item.name || 'Untitled';
    body.appendChild(h3);

    // Static price display
    const priceRow = document.createElement('div');
    priceRow.className = 'card-footer';
    const priceDisplay = document.createElement('div');
    priceDisplay.className = 'card-price';
    const priceNum = parseFloat(item.price) || 0;
    priceDisplay.textContent = '$' + priceNum.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    priceDisplay.style.cssText = 'background:var(--paper); border:1px solid var(--line); border-radius:6px; padding:6px 10px; width:100%; font-family:var(--mono); color:var(--ink); text-align:center; font-weight:700;';
    priceRow.appendChild(priceDisplay);
    body.appendChild(priceRow);

    card.appendChild(body);
    grid.appendChild(card);
  });
}

document.addEventListener('DOMContentLoaded', () => {
  renderTrackerGrid();

  document.querySelectorAll('#tracker-filters .filter-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      document.querySelectorAll('#tracker-filters .filter-chip').forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      trackerFilter = chip.dataset.status;
      renderTrackerGrid();
    });
  });

  const search = document.getElementById('tracker-search');
  if (search) {
    search.addEventListener('input', () => {
      trackerSearchTerm = search.value;
      renderTrackerGrid();
    });
  }
});
